from pathlib import Path
from html import escape
import json
import sys
ROOT=Path(__file__).resolve().parents[1]
CHECK='--check' in sys.argv
GENERATED={}
def write(path, content):
    relative=path.relative_to(ROOT).as_posix()
    assert relative in {'index.html','demo.html','beta.html','principles.html','status.html','about.html','privacy-policy.html','terms.html','thanks.html','404.html','sitemap.xml','robots.txt'} or (relative.startswith('en/') and relative.count('/')==1 and relative.endswith('.html'))
    GENERATED[relative]=content
    if not CHECK:
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(content,encoding='utf-8')
BASE='https://inputarchive.com'
EMAIL='haohongfei2001@gmail.com'

def build(lang):
    en=lang=='en'
    prefix='/en/' if en else '/'
    def t(zh,eng): return eng if en else zh
    def link(page='index.html',anchor=''):
        return prefix + ('' if page=='index.html' else page) + anchor
    def a(page,label,cls='',anchor=''):
        return f'<a class="{cls}" href="{link(page,anchor)}">{label}</a>'
    def button(page,label,cls='button',anchor=''):
        return a(page,label+' <span aria-hidden="true">→</span>',cls,anchor)
    def head(page,title,desc,noindex=False):
        url=BASE+link(page)
        zhurl=BASE+'/'+('' if page=='index.html' else page)
        enurl=BASE+'/en/'+('' if page=='index.html' else page)
        return f'''<!doctype html>
<html lang="{'en' if en else 'zh-CN'}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)}</title>
<meta name="description" content="{escape(desc,quote=True)}">
<meta name="theme-color" content="#f5f4ef">
<meta name="referrer" content="strict-origin-when-cross-origin">
{'<meta name="robots" content="noindex,follow">' if noindex else ''}
<link rel="canonical" href="{url}">
<link rel="alternate" hreflang="zh-Hans" href="{zhurl}">
<link rel="alternate" hreflang="en" href="{enurl}">
<link rel="alternate" hreflang="x-default" href="{zhurl}">
<meta property="og:type" content="website">
<meta property="og:site_name" content="PAIA">
<meta property="og:locale" content="{'en_US' if en else 'zh_CN'}">
<meta property="og:title" content="{escape(title,quote=True)}">
<meta property="og:description" content="{escape(desc,quote=True)}">
<meta property="og:url" content="{url}">
<meta property="og:image" content="{BASE}/assets/website/og-{lang}.png">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:image:alt" content="{t('PAIA：聊过的想法，不止留在聊天里。','PAIA: Your words. Beyond the chat.')}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="{escape(title,quote=True)}">
<meta name="twitter:description" content="{escape(desc,quote=True)}">
<meta name="twitter:image" content="{BASE}/assets/website/og-{lang}.png">
<link rel="icon" href="/assets/website/favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="/assets/website/site.css?v=1">
<script src="/assets/website/site.js?v=1" defer></script>
</head>
<body>
<a class="skip-link" href="#main">{t('跳到正文','Skip to content')}</a>'''
    def header(page):
        other=('/'+('' if page=='index.html' else page)) if en else ('/en/'+('' if page=='index.html' else page))
        nav=a('index.html',t('如何使用','How it works'),anchor='#how')+a('principles.html',t('数据与信任','Your data'))+a('status.html',t('当前状态','What’s ready'))
        nav=nav.replace(f'href="{link(page)}"', f'href="{link(page)}" aria-current="page"')
        return f'''<header class="site-header"><div class="header-inner">
<a class="wordmark" href="{prefix}" aria-label="{t('PAIA 首页','PAIA home')}">PAIA<span class="brand-rule" aria-hidden="true"></span></a>
<nav class="desktop-nav" aria-label="{t('主导航','Main navigation')}">{nav}</nav>
<div class="header-actions"><a class="language" href="{other}" lang="{'zh-CN' if en else 'en'}" hreflang="{'zh-Hans' if en else 'en'}">{t('EN','中文')}</a>{button('beta.html',t('申请内测','Request beta'),'button button-small')}</div>
<details class="mobile-menu"><summary aria-label="{t('打开导航菜单','Open navigation menu')}"><span aria-hidden="true">☰</span></summary><nav aria-label="{t('移动端导航','Mobile navigation')}">{nav}{a('demo.html',t('示例体验','Try a sample'))}</nav></details>
</div></header>'''
    def footer():
        return f'''<footer class="site-footer wrap"><div class="footer-top"><a class="wordmark" href="{prefix}">PAIA</a><p>{t('先属于你，再由你决定如何使用。','Yours first. Shared on your terms.')}</p></div><div class="footer-bottom"><nav aria-label="{t('页脚导航','Footer navigation')}">{a('about.html',t('为什么做 PAIA','Why PAIA'))}{a('status.html',t('当前状态','Status'))}{a('privacy-policy.html',t('隐私政策','Privacy'))}{a('terms.html',t('使用条款','Terms'))}<a href="mailto:{EMAIL}">{t('联系','Contact')}</a></nav><span>© 2026 PAIA · Private Beta</span></div></footer>'''
    def shell(page,title,desc,body,noindex=False,extra=''):
        out=head(page,title,desc,noindex)+header(page)+f'<main id="main" tabindex="-1">{body}</main>'+footer()+extra+'\n</body>\n</html>\n'
        dest=ROOT/('en' if en else '')/page
        dest.parent.mkdir(parents=True,exist_ok=True)
        write(dest,out)
    def invitation():
        return f'''<section class="invitation wrap"><p class="eyebrow">PAIA · PRIVATE BETA</p><h2>{t('给下一次思考，<br>留一点来处。','Give your next thought<br>somewhere to begin.')}</h2><p>{t('从你已经在说的话开始，不必再养成一种记录习惯。','Start with the words you already write. Not another habit to maintain.')}</p><div class="actions">{button('beta.html',t('申请 Private Beta','Request beta access'))}{a('demo.html',t('先用示例试一遍','Try a sample first'),'text-link')}</div></section>'''
    def statusmini():
        return f'''<div class="availability"><span class="status-dot" aria-hidden="true"></span><span>{t('桌面 Chrome 扩展 · ChatGPT 网页版 · 邀请制测试','Desktop Chrome extension · ChatGPT Web · Invite-only beta')}</span></div>'''
    def story_sample():
        return f'''<figure class="hero-folio" aria-label="{t('把过去表达用于新任务的示例','An example of reusing past expressions')}"><div class="folio-top"><span>{t('一个持续中的项目','AN ONGOING PROJECT')}</span><span>{t('周末小刊','Weekend letters')}</span></div>
<div class="folio-record"><span class="sample-date">08.12 <span>／ {t('写作方向','Writing direction')}</span></span><blockquote>{t('“我不想追热点。每期只写一个真正想弄清楚的问题。”','“I don’t want to chase trends. Each letter should explore one question I genuinely want to understand.”')}</blockquote></div>
<div class="folio-record"><span class="sample-date">09.03 <span>／ {t('读者与节奏','Readers & rhythm')}</span></span><blockquote>{t('“写给刚开始工作的人。短一点，但要留下一个具体的观察。”','“Write for people starting their working lives. Keep it short, but leave them with one concrete observation.”')}</blockquote></div>
<div class="folio-reuse"><span class="eyebrow">{t('今天 · 再次用于 AI','TODAY · USE WITH AI')}</span><p>{t('为下一期小刊准备开头，<br>延续我之前确定的方向。','Help me open the next letter.<br>Build on the direction I’ve already chosen.')}</p><div class="folio-bottom"><span>{t('已选择 2 条表达','2 expressions selected')}</span><span>{t('先预览，再复制','Review before copying')} ↗</span></div></div>
<figcaption>{t('能力示意 · 虚构内容，非产品截图','Capability illustration · Fictional content, not a product screenshot')}</figcaption></figure>'''
    home=f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">{t('你的私人 AI 输入与上下文空间','A PRIVATE HOME FOR WHAT YOU TELL AI')}</p><h1>{t('聊过的想法，<br>不止留在聊天里。','Your words.<br>Beyond the chat.')}</h1><p class="hero-description">{t('PAIA 把你向 ChatGPT 表达过的信息和想法，留在你自己的档案里。找回来、看清楚、修改，再带进下一次 AI 对话。','PAIA keeps what you tell ChatGPT in an archive of your own. Find it, make sense of it, edit it, and bring it into your next AI conversation.')}</p><div class="actions">{button('demo.html',t('试一次找回与复用','Try a sample'))}{a('beta.html',t('申请 Private Beta','Request beta access'),'text-link')}</div>{statusmini()}<p class="hero-note">{t('本机保存 · 原话与修改分开 · 对外使用由你决定','Stored locally · Originals kept separate · You choose what leaves')}</p></div>{story_sample()}</section>
<section class="question-section wrap" id="why"><p class="eyebrow">{t('窗口换了，正在想的事还没有结束','A NEW CHAT ISN’T A NEW BEGINNING')}</p><h2>{t('“这件事，我以前认真想过。”','“I know I’ve thought this through before.”')}</h2><p class="section-intro">{t('一段决定的来由，一个反复推敲的想法，一次修正过的判断。值得留下的，不只是 AI 给出的答案，也包括你一路表达过的东西。','The reason behind a decision. An idea you keep returning to. An assumption you corrected. The valuable part isn’t only what AI answered. It’s what you brought to the conversation.')}</p><div class="situations"><article><span>01</span><h3>{t('继续一个项目','Continue a project')}</h3><p>{t('找回之前确定的方向和限制，不必在新窗口重新交代。','Recover the direction and constraints you already established, instead of explaining them again.')}</p></article><article><span>02</span><h3>{t('重新考虑一个决定','Reconsider a decision')}</h3><p>{t('看看当时为什么这样选，而不只剩下今天的结论。','Return to why you made a choice, not just the conclusion you remember today.')}</p></article><article><span>03</span><h3>{t('接着研究、学习或创作','Keep learning and creating')}</h3><p>{t('把不同会话中的问题和观察放在一起，接着往下想。','Bring questions and observations from separate chats together, then take the next step.')}</p></article></div></section>
<section class="journey-section" id="how"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">CAPTURE → REVISIT → UNDERSTAND → REUSE</p><h2>{t('从“我记得说过”，<br>到“这次接着用”。','From “I said this somewhere”<br>to “let’s build on it.”')}</h2></div><p>{t('不必先整理成一套知识库。先留下，下一次需要时，就有地方可找。','You don’t need to organize a knowledge base first. Keep your words, then return when you need them.')}</p></div><div class="journey"><article><span class="step-number">01 / CAPTURE</span><h3>{t('照常说，留下来。','Keep talking. Keep your words.')}</h3><p>{t('明确同意后，扩展在支持的 ChatGPT 页面保存符合条件、已显示的用户文字。不是键盘记录，也不是整个账户的自动备份。','After consent, the extension captures eligible, displayed user text on supported ChatGPT pages. Not keystrokes or an automatic backup of your entire account.')}</p><small>Input Archive</small></article><article><span class="step-number">02 / REVISIT</span><h3>{t('用熟悉的线索找回。','Find a familiar thread.')}</h3><p>{t('按会话和项目浏览，用关键词定位，再回到连续的阅读正文。你看到的，是自己说过的具体内容。','Browse conversations and projects, search by keyword, and return to the surrounding text. Read the actual expressions, not just a summary.')}</p><small>Input Archive</small></article><article><span class="step-number">03 / UNDERSTAND</span><h3>{t('看见同一件事的脉络。','See one idea across chats.')}</h3><p>{t('在长期主题里放在一起看，继续补充和思考。可选 AI 整理帮助梳理结构，不应该替你发明观点。','Read related expressions together in a lasting topic. Optional AI organization helps with structure; it should not invent your beliefs.')}</p><small>Thought Library</small></article><article><span class="step-number">04 / REUSE</span><h3>{t('选一点，接着用。','Choose a little. Build on it.')}</h3><p>{t('从档案或主题选材料，准备并检查上下文，再明确复制或导出。没有整理进思想库的输入，也能直接使用。','Select material from the archive or a topic, prepare and review context, then explicitly copy or export it. Inputs do not have to enter Thought Library first.')}</p><small>AI Context</small></article></div><div class="section-end">{a('demo.html',t('用同一个例子，完整试一遍','Try the whole loop with one example'),'text-link')}<span>{t('无需安装 · 不读取你的档案 · 不调用 AI','No installation · No archive access · No AI calls')}</span></div></div></section>
<section class="memory-section wrap" id="memory"><div><p class="eyebrow">{t('已经有聊天历史和 MEMORY？','ALREADY HAVE CHAT HISTORY AND MEMORY?')}</p><h2>{t('不是替 AI 再记一遍。<br>是让你自己也能掌握。','Not another memory for AI.<br>A record you can work with.')}</h2><p>{t('聊天历史适合找回和继续对话。Memory 让后续回答更贴近你。PAIA 关注另一件事：让你表达过的内容，成为可阅读、可修改、可带走、可主动复用的私人材料。','Chat history helps you return to conversations. Memory personalizes future responses. PAIA focuses on something different: making your expressions readable, editable, portable, and available for deliberate reuse.')}</p><p class="small">{t('它们可以一起使用，不需要停用 Memory。','They can work together. You do not need to turn Memory off.')} <a href="https://help.openai.com/en/articles/8590148-memory-in-chatgpt" rel="noreferrer">{t('了解 ChatGPT Memory','About ChatGPT Memory')} ↗</a></p></div><div class="distinctions"><div><span>{t('当你想找回','When you need to recover')}</span><p>{t('不只问“AI 记住了什么”，<br>也能看“我当时到底说过什么”。','Not only “what does AI remember?”<br>Also “what exactly did I say?”')}</p></div><div><span>{t('当你想修正','When you need to revise')}</span><p>{t('修改现在要用的文字，<br>不把修改冒充成过去的原话。','Edit what you want to use now,<br>without rewriting the original record.')}</p></div><div><span>{t('当你想再用','When you need to reuse')}</span><p>{t('自己挑选这次需要的部分，<br>而不是把整个档案交出去。','Choose the material for this task,<br>rather than hand over the whole archive.')}</p></div></div></section>
<section class="trust-preview" id="trust"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">{t('长期私人数据，需要具体的边界','PRIVATE DATA NEEDS REAL BOUNDARIES')}</p><h2>{t('先属于你，<br>再由你决定如何使用。','Yours first.<br>Shared on your terms.')}</h2></div><p>{t('信任不靠一句“安全”。它体现在什么被保存、什么可以修改、什么会离开设备，以及你怎样离开这个产品。','Trust is not a “secure” badge. It is what gets kept, what can change, what leaves the device, and how you can leave the product.')}</p></div><div class="trust-grid"><article><h3>{t('日常使用，在本机','Everyday work stays local')}</h3><p>{t('核心档案保存在扩展本地。阅读、编辑、关键词搜索和上下文准备不需要外部 AI。请为重要资料保留独立备份。','The core archive lives in local extension storage. Reading, editing, lexical search, and context preparation do not require external AI. Keep independent backups of important data.')}</p></article><article><h3>{t('原话、修改、AI 整理分开','Originals, edits, and AI are distinct')}</h3><p>{t('普通编辑不覆盖原始来源记录。AI 整理是另一层呈现，不应该静默改写你的人工工作，也不能把引用当成你的立场。','Ordinary editing does not overwrite Source records. AI organization is another presentation, not permission to silently replace your work or treat a quotation as your belief.')}</p></article><article><h3>{t('保存，不等于授权 AI 使用','Keeping is not permission to share')}</h3><p>{t('可选外部 AI 处理需要明确操作。复制、导出或授权发送后，外部副本无法被 PAIA 收回；关闭访问只影响之后受控的访问。','Optional external AI processing requires an explicit action. PAIA cannot recall copies you export or send elsewhere. Revocation only affects future access that PAIA controls.')}</p></article></div>{a('principles.html',t('看看完整的数据与授权边界','Read the data and permission boundaries'),'text-link')}</div></section>
<section class="now-section wrap" id="now"><div><p class="eyebrow">{t('现在的 PAIA','PAIA TODAY')}</p><h2>{t('从一个诚实的 Beta 开始。','An honest place to start.')}</h2>{statusmini()}<p>{t('当前产品是围绕 ChatGPT 网页版开发的桌面 Chrome 扩展，正在邀请制测试。官网可以在手机上浏览，示例也可以体验；这不代表已有手机 App。','The current product is a desktop Chrome extension centered on ChatGPT Web, in invite-only testing. This website and its sample work on phones; that does not mean a mobile app is available.')}</p>{a('status.html',t('查看已实现、待验证与后续方向','See what’s implemented, being verified, and planned'),'text-link')}</div><div class="status-list"><div><span class="label">{t('当前代码已有','IN THE CURRENT BUILD')}</span><p>{t('输入档案 · 会话阅读与编辑 · 关键词搜索 · 主题阅读 · 选材料、预览、复制与导出','Input archive · Conversation reading and editing · Keyword search · Topics · Material selection, preview, copy and export')}</p></div><div><span class="label">{t('仍在完善和验证','STILL BEING VERIFIED')}</span><p>{t('真实环境兼容性 · 历史导入 · 大库备份恢复 · 消费级分发与更新','Live-site compatibility · History import · Large-library backup and restore · Consumer distribution and updates')}</p></div><div><span class="label">{t('不是当前上线承诺','NOT AVAILABLE AS A CURRENT RELEASE')}</span><p>{t('手机 App · 通用云同步 · 更多来源 · 让外部 AI 直接读取档案的连接器','Mobile app · General cloud sync · More sources · A connector for external AI to read your archive directly')}</p></div></div></section>
<section class="faq-section wrap"><h2>{t('开始之前，你可能想知道。','A few things before you begin.')}</h2><div class="faq"><details><summary>{t('会收集我的草稿、AI 回复或临时聊天吗？','Does it collect drafts, AI replies, or Temporary Chats?')}</summary><p>{t('当前采集边界围绕符合条件、已显示的用户文字，不默认保存草稿、按键或 AI 回复。Temporary Chat 不自动采集。你发送的引用或第三方文本，也不应被自动当成你的个人观点。','Current capture is bounded to eligible, displayed user text, not drafts, keystrokes, or AI replies by default. Temporary Chat is not automatically captured. Quoted or third-party text you send should not automatically become a personal belief.')}</p></details><details><summary>{t('需要手动整理每条输入吗？','Do I have to organize every input?')}</summary><p>{t('不需要。档案浏览、阅读和搜索本身就有价值。主题组织和可选 AI 整理是帮助理解的能力，不是开始使用或复用材料的前提。','No. Browsing, reading, and searching the archive are useful on their own. Topics and optional AI organization help you understand material; they are not prerequisites for using it again.')}</p></details><details><summary>{t('停止使用 PAIA 后，内容还能带走吗？','Can I take my material with me?')}</summary><p>{t('当前代码提供开放导出和备份路径。导出用于带走可读材料，备份用于恢复库，两者不相同。Beta 阶段不要把 PAIA 当成重要资料的唯一副本；支持范围和恢复验证仍在完善。','The current code provides open export and backup paths. Export is for portable material; backup is for restoring a library. They are different. During beta, do not use PAIA as your only copy of important data; support limits and restore verification are still being refined.')}</p></details><details><summary>{t('我的 AI 会自动读到这些内容吗？','Will my AI automatically see the archive?')}</summary><p>{t('不会。当前官网展示的复用路径是：明确选材料、检查上下文，再由你复制或导出使用。真正的外部 AI 连接器属于后续方向，不能把预览当成已经发送。','No. The reuse path shown here is deliberate selection, review, then copy or export. A real external AI connector is a future direction. A preview is not a transmission.')}</p></details></div></section>{invitation()}'''
    shell('index.html',t('PAIA — 聊过的想法，不止留在聊天里','PAIA — Your words. Beyond the chat.'),t('PAIA 是本地优先的私人 AI 输入档案与上下文空间。找回、理解、编辑你向 ChatGPT 表达过的内容，再用于下一次 AI 对话。桌面 Chrome 扩展，Private Beta。','A local-first archive for what you tell ChatGPT. Find, understand, edit and reuse your expressions in your next AI conversation. Desktop Chrome extension, private beta.'),home)

    # Every record is fictional; no private-source prose or user archive material.
    records=[('a','2026-08-12',t('写作方向','Writing direction'),t('我不想追热点。每期只写一个真正想弄清楚的问题。','I don’t want to chase trends. Each letter should explore one question I genuinely want to understand.')),
             ('b','2026-09-03',t('读者与节奏','Readers and rhythm'),t('写给刚开始工作的人。短一点，但要留下一个具体的观察。','Write for people starting their working lives. Keep it short, but leave them with one concrete observation.')),
             ('c','2026-09-15',t('内容边界','Content boundaries'),t('下期先写一次失败的尝试。不要替读者给出一个万能答案。','Next time, start with an attempt that failed. Don’t offer readers a universal answer.'))]
    recordhtml=''.join(f'''<article class="sample-record" data-record="{id}"><div class="record-meta"><span>{date}</span><span>{escape(title)}</span></div><label for="edit-{id}">{t('现在要用的文字','Working text')}</label><textarea id="edit-{id}" class="working-text" rows="3" spellcheck="false">{escape(text)}</textarea><details class="source-details"><summary>{t('核对原始记录','Check the original record')}</summary><blockquote class="source-text">{escape(text)}</blockquote><p>{t('这是此示例的固定原始记录，编辑上方文字不会改变它。','This is the fixed original in this sample. Editing the working text above does not change it.')}</p></details></article>''' for id,date,title,text in records)
    choices=''.join(f'''<label class="material-choice"><input type="checkbox" data-select="{id}" {'checked' if id!='c' else ''}><span><strong>{escape(title)}</strong><small>{date}</small></span></label>''' for id,date,title,text in records)
    demo=f'''<section class="page-intro wrap"><p class="eyebrow">{t('一个示例，走完一次复用','ONE EXAMPLE. ONE COMPLETE REUSE.')}</p><h1>{t('把过去说过的话，<br>用在这次。','Put your past words<br>to work, this time.')}</h1><p class="lead">{t('你在准备下一期“周末小刊”。试着找回写作方向，改一句现在要用的话，再挑选要带给 AI 的内容。','You’re preparing the next Weekend Letter. Find your earlier direction, edit a working sentence, and choose what to give AI next.')}</p><div class="demo-disclosure"><strong>{t('交互示意，不是正在运行的扩展','An interactive illustration, not the running extension')}</strong><p>{t('全部为虚构数据。不连接你的 ChatGPT 或 PAIA，不调用 AI，不上传或持久保存本页输入。刷新会清除修改；请不要输入私人资料。','All data is fictional. This page does not connect to ChatGPT or PAIA, call AI, upload your input, or persist it. Reloading clears edits. Please do not enter private information.')}</p></div></section>
<section class="demo wrap" data-demo data-language="{lang}"><noscript><p class="notice">{t('开启 JavaScript 后可体验编辑、选择和复制。下面的示例说明可直接阅读，申请表也不依赖 JavaScript。','Enable JavaScript to try editing, selection and copying. You can still read this explanation and use the beta form without JavaScript.')}</p></noscript><div class="demo-tabs" role="tablist" aria-label="{t('体验步骤','Demo steps')}">{''.join(f'<button role="tab" id="tab-{i}" aria-controls="panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-step="{i}"><span>0{i+1}</span>{name}</button>' for i,name in enumerate([t('留下','Capture'),t('找回与修改','Revisit'),t('理解','Understand'),t('复用','Reuse')]))}</div>
<section id="panel-0" class="demo-panel" role="tabpanel" aria-labelledby="tab-0"><div class="demo-panel-heading"><p class="eyebrow">01 / CAPTURE</p><h2>{t('先有自己的记录。','First, a record of your own.')}</h2><p>{t('正式扩展在你明确同意后保存支持页面上的用户文字。这个例子已经准备好三条输入，来自同一个项目里的不同会话。','The extension saves eligible user text on supported pages after your consent. This sample already contains three inputs from separate conversations in one project.')}</p></div><div class="capture-sample"><span class="label">{t('示例项目','SAMPLE PROJECT')}</span><h3>{t('周末小刊','Weekend letters')}</h3>{''.join(f'<p><time datetime="{d}">{d}</time><span>{escape(title)}</span></p>' for _,d,title,_ in records)}</div><p class="small">{t('这个页面没有执行采集。打开旧对话的补录，也不等于导入整个账户的历史。','No capture happens on this page. Supplementing an opened conversation is not the same as importing your entire account history.')}</p><button class="button" data-next disabled>{t('找回写作方向','Find the writing direction')} <span aria-hidden="true">→</span></button></section>
<section id="panel-1" class="demo-panel" role="tabpanel" aria-labelledby="tab-1" hidden><div class="demo-panel-heading"><p class="eyebrow">02 / REVISIT</p><h2>{t('找回来，也可以继续修改。','Find it. Then work with it.')}</h2><p>{t('搜“读者”试试，再直接改一句工作文字。展开原始记录，看看有什么没有改变。','Try searching for “readers”, then edit a working sentence. Open the original record to see what stays unchanged.')}</p></div><label class="search-label" for="sample-search">{t('在这三条示例输入中查找','Search these three sample inputs')}</label><input type="search" id="sample-search" placeholder="{t('试试：读者','Try: readers')}" autocomplete="off"><p id="search-status" class="small" role="status"></p><div class="sample-records">{recordhtml}</div><p class="empty-search" hidden>{t('没有匹配。试试另一个关键词，或清空搜索。','No match. Try another keyword or clear the search.')}</p><button class="button" data-next>{t('放在一个主题里看','See the topic')} <span aria-hidden="true">→</span></button></section>
<section id="panel-2" class="demo-panel" role="tabpanel" aria-labelledby="tab-2" hidden><div class="demo-panel-heading"><p class="eyebrow">03 / UNDERSTAND</p><h2>{t('同一个主题，不同时间的表达。','One topic. Expressions over time.')}</h2><p>{t('会话告诉你在哪里说过；主题帮助你把相关内容放在一起看。下方会跟随此示例中的工作文字，不额外推断你的立场。','Conversations tell you where you said something. A topic brings related expressions together. This sample uses the working text you just edited, without inferring new beliefs.')}</p></div><div class="topic-sample"><div class="topic-heading"><h3>{t('我的小刊，写给谁，怎么写','Who I write for. How I want to write.')}</h3><span class="small">{t('固定示例主题','Fixed sample topic')}</span></div><div data-topic-records></div></div><p class="small">{t('这里不运行自动分类或 AI 整理。正式产品中的可选 AI 整理属于另外授权的处理，不能把输出当成未经核对的个人事实。','This page does not run automatic classification or AI organization. Optional AI organization in the product is separately authorized processing, not an unchecked source of personal facts.')}</p><button class="button" data-next>{t('为这次任务选材料','Choose material for this task')} <span aria-hidden="true">→</span></button></section>
<section id="panel-3" class="demo-panel" role="tabpanel" aria-labelledby="tab-3" hidden><div class="demo-panel-heading"><p class="eyebrow">04 / REUSE</p><h2>{t('只带上这次需要的。','Take only what this task needs.')}</h2><p>{t('选择、预览，再复制或导出。更改任务、选择或工作文字后，需要重新准备预览，不会默默输出旧版本。','Select, review, then copy or export. Changing the task, selection or working text requires a fresh preview, rather than silently releasing an older version.')}</p></div><div class="context-layout"><div><label for="sample-task">{t('这次要做什么？','What are you doing this time?')}</label><textarea id="sample-task" rows="3">{t('为下一期小刊准备一个开头，延续我的写作方向。','Help me write an opening for the next letter, building on my writing direction.')}</textarea><fieldset><legend>{t('你明确选择的材料','Material you explicitly choose')}</legend>{choices}</fieldset><button class="button" data-build>{t('准备本地预览','Prepare local preview')}</button></div><div class="context-output"><label for="context-preview">{t('将要复制或导出的完整文字','The exact text to copy or export')}</label><textarea id="context-preview" rows="12" readonly placeholder="{t('还没有准备上下文，也没有发送任何内容。','No context prepared. Nothing has been sent.')}"></textarea><p class="context-status small" role="status">{t('未发送给任何 AI','Not sent to any AI')}</p><div class="actions"><button class="button" data-copy disabled>{t('复制文字','Copy text')}</button><button class="button button-outline" data-export disabled>{t('导出 Markdown','Export Markdown')}</button></div><p class="small">{t('复制和导出只在你点击后发生。PAIA 无法收回你之后交给外部系统的副本。','Copy and export happen only when you click. PAIA cannot recall a copy you later give to another system.')}</p></div></div></section><div class="demo-bottom"><button class="text-button" data-reset disabled>{t('重置示例，清除本页修改','Reset sample and clear edits')}</button><span class="small" data-demo-status role="status"></span>{a('beta.html',t('这对我有用，申请内测','This is useful — request beta access'),'text-link')}</div></section>'''
    shell('demo.html',t('用一个示例体验 PAIA — 找回、修改、复用','Try PAIA with a sample — Find, edit, reuse'),t('用虚构项目走完 PAIA 的找回与复用。无需安装，不连接私人档案，不调用 AI。','Explore PAIA with a fictional project. No installation, private archive access or AI calls.'),demo,True,'<script src="/assets/website/demo.js?v=1" defer></script>')

    beta=f'''<section class="page-intro wrap"><p class="eyebrow">PAIA · PRIVATE BETA</p><h1>{t('让你真正遇到的问题，<br>进入下一版 PAIA。','Bring a real problem<br>to the next PAIA.')}</h1><p class="lead">{t('适合已经经常用 ChatGPT 思考、研究或创作，也确实遇到过“以前说过，却难以继续使用”的人。','For people who regularly think, research or create with ChatGPT—and have struggled to put past expressions to use again.')}</p>{statusmini()}</section><section class="beta-layout wrap"><div><form class="beta-form" action="https://formsubmit.co/haohongfei2001@gmail.com" method="POST"><input type="hidden" name="_subject" value="PAIA Private Beta application"><input type="hidden" name="_template" value="table"><input type="hidden" name="_captcha" value="false"><input type="hidden" name="_next" value="{BASE}{link('thanks.html')}"><input type="hidden" name="language" value="{lang}"><div class="honeypot" aria-hidden="true"><label for="website-url">Leave this field empty</label><input id="website-url" type="text" name="_honey" tabindex="-1" autocomplete="off"></div><h2>{t('申请加入测试','Request an invitation')}</h2><label for="beta-email">{t('邮箱','Email')} <span class="required">{t('必填','Required')}</span></label><input id="beta-email" name="email" type="email" autocomplete="email" required maxlength="254" aria-describedby="email-hint"><p class="field-hint" id="email-hint">{t('用于 Beta 联系和邀请，不要求填写真实姓名。','For beta contact and invitations. No real name required.')}</p><label for="beta-frequency">{t('你使用 ChatGPT 的频率','How often do you use ChatGPT?')}</label><select id="beta-frequency" name="frequency"><option value="">{t('选填','Optional')}</option><option value="daily">{t('每天','Daily')}</option><option value="several-times-week">{t('每周数次','Several times a week')}</option><option value="weekly-or-less">{t('每周或更少','Weekly or less')}</option></select><label for="beta-goal">{t('你最想找回或复用什么？','What would you like to recover or reuse?')}</label><textarea id="beta-goal" name="goal" rows="4" maxlength="1000" placeholder="{t('选填。描述一个场景即可，不要粘贴聊天记录或私人资料。','Optional. Describe a situation, not private information or actual chat text.')}" aria-describedby="form-privacy"></textarea><label class="consent"><input type="checkbox" name="contact_consent" value="yes" required><span>{t('我同意将以上申请信息交给 FormSubmit 转发至项目邮箱，用于 Beta 招募与联系。','I agree to have FormSubmit forward this application to the project email for beta recruitment and contact.')}</span></label><p class="small" id="form-privacy">{t('只有提交此表单才会发送这些信息。不会发送你的 PAIA 档案。可随时通过项目邮箱申请删除；请勿填写敏感信息。','Only submitting this form sends this information. It does not send your PAIA archive. You can request deletion through the project email. Do not include sensitive information.')} {a('privacy-policy.html',t('隐私政策','Privacy policy'))}</p><button class="button" type="submit">{t('提交申请','Submit application')} <span aria-hidden="true">↗</span></button><p class="small">{t('提交后将前往 FormSubmit 处理。以该服务的提交结果为准；申请不代表已经获邀。','Submission is handled by FormSubmit. Its response determines delivery; applying does not mean you have been invited.')}</p></form><p class="small form-alternative">{t('表单无法使用？也可以直接写信：','Form unavailable? You can email instead:')} <a href="mailto:{EMAIL}?subject=PAIA%20Private%20Beta">{EMAIL}</a></p></div><aside class="beta-aside"><h2>{t('申请后会怎样','What happens next')}</h2><ol class="steps-list"><li><h3>{t('我们了解你的使用场景','We review your use case')}</h3><p>{t('招募以当前测试范围为准，不承诺固定回复时间或一定获得名额。','Invitations depend on the current testing scope. There is no guaranteed place or response time.')}</p></li><li><h3>{t('获邀后收到安装说明','Invited participants receive instructions')}</h3><p>{t('包括可用版本、安装方式、当前限制和反馈方式。不是立即安装，也不是公开商店发布。','Including the available build, setup, limitations and feedback path. This is not an instant installation or public store release.')}</p></li><li><h3>{t('从非关键材料开始','Start with non-critical material')}</h3><p>{t('先验证保存、找回和复用是否适合你。重要资料始终保留独立备份。','Check whether capture, retrieval and reuse help you. Always keep independent backups of important data.')}</p></li></ol><div class="aside-note"><strong>{t('还不确定？','Still exploring?')}</strong><p>{t('先用示例体验，不需要提供邮箱。','Try the sample first. No email needed.')}</p>{a('demo.html',t('打开示例','Open the sample'),'text-link')}</div></aside></section>'''
    shell('beta.html',t('申请 PAIA Private Beta','Request PAIA Private Beta access'),t('申请参与 PAIA 邀请制测试。桌面 Chrome 扩展，围绕 ChatGPT 网页版；先查看范围、数据边界和申请流程。','Request an invitation to test PAIA for desktop Chrome and ChatGPT Web. Review the scope, data boundaries and application process.'),beta)

    trust=f'''<section class="page-intro wrap"><p class="eyebrow">{t('数据与信任','DATA & TRUST')}</p><h1>{t('长期留下，<br>不等于交出控制。','Keep it for the long term.<br>Keep control of it.')}</h1><p class="lead">{t('PAIA 首先是你自己的私人材料，不是默认交给模型消费的数据。下面说明当前设计与实现中的具体边界，而不是一份无限安全的承诺。','PAIA is your private material first, not a default data feed for a model. These are concrete boundaries in the current design and implementation, not a promise of absolute security.')}</p></section><section class="article-layout wrap"><nav class="article-nav" aria-label="{t('本页目录','On this page')}"><a href="#local">{t('本机与外部','Local and external')}</a><a href="#source">{t('原话与修改','Originals and edits')}</a><a href="#permission">{t('不同的授权','Separate permissions')}</a><a href="#exit">{t('备份与离开','Backup and exit')}</a></nav><div class="prose"><section id="local"><h2>{t('日常使用不必先把档案上传。','Everyday use does not require an archive upload.')}</h2><p>{t('核心档案默认保存在 Chrome 扩展的本地存储中。普通阅读、编辑、词面搜索以及上下文准备在本机完成。这个官网不连接你的扩展档案。','The core archive is stored locally in the Chrome extension. Ordinary reading, editing, lexical search and context preparation happen on-device. This website does not connect to your extension archive.')}</p><p>{t('“本地优先”不等于“任何情况下都不出设备”。主动使用可选外部 AI 整理时，当前版本可向配置的 DeepSeek API 发送获准处理的材料；手动复制、导出或在其他系统使用材料，也会产生外部副本。','“Local-first” does not mean “nothing can ever leave the device.” Explicit use of optional external AI organization can send authorized material to the configured DeepSeek API in the current build. Copying, exporting or using material in another system can also create external copies.')}</p><p>{t('本机保存不是加密声明，也不能抵御设备被入侵、浏览器资料被删除或所有存储故障。请保护设备，并保留独立备份。','Local storage is not an encryption claim. It cannot protect against every compromised device, deleted browser profile or storage failure. Protect your device and keep independent backups.')}</p></section><section id="source"><h2>{t('今天修改文字，不改写昨天发生的事。','Editing today does not rewrite yesterday.')}</h2><p>{t('Source 记录保存来源事实；工作文字用于日常阅读和修改；AI 整理是基于材料生成的呈现。普通编辑不覆盖 Source。用户手动修改和排除，不应该被自动处理悄悄覆盖。','Source records preserve what came from the source. Working text is for everyday reading and editing. AI organization is a presentation derived from that material. Ordinary edits do not overwrite Source. Automatic processing should not silently undo your edits or exclusions.')}</p><div class="source-comparison"><div><span class="label">{t('原始记录 · 示例','ORIGINAL RECORD · EXAMPLE')}</span><p>{t('每期只写一个真正想弄清楚的问题。','Each letter should explore one question I genuinely want to understand.')}</p></div><div><span class="label">{t('现在的工作文字 · 示例','CURRENT WORKING TEXT · EXAMPLE')}</span><p>{t('每期从一个具体观察出发，讨论一个真正想弄清楚的问题。','Begin each letter with a concrete observation, then explore one question I genuinely want to understand.')}</p></div></div><p>{t('发送过一段文字，也不自动意味着认同它。引用、第三方材料、假设和角色扮演，都不能无条件被归结为你的长期观点。AI 整理仍需要核对，不应编造一段顺滑的“思想成长史”。','Sending a passage does not necessarily mean believing it. Quotes, third-party material, hypotheses and role-play should not automatically become your lasting opinions. Review AI organization; it should not invent a tidy story of personal growth.')}</p></section><section id="permission"><h2>{t('四件事，四种边界。','Four actions. Separate boundaries.')}</h2><dl class="boundary-list"><div><dt>{t('保存输入','Keep inputs')}</dt><dd>{t('授权扩展保留符合条件的用户文字。不是许可任意读取其他页面、草稿或文件。','Consent to retain eligible user text. Not permission to read arbitrary pages, drafts or files.')}</dd></div><div><dt>{t('调用外部 AI','Use external AI')}</dt><dd>{t('另外明确触发，对获准范围进行处理。不是因为已经保存，就自动允许上传。','A separate, explicit action over authorized material. Retention is not permission to upload.')}</dd></div><div><dt>{t('复制或导出 Context','Copy or export context')}</dt><dd>{t('先选择并预览，再由你实际使用。不代表已经发给 AI，也不能收回外部副本。','Select and preview, then use it yourself. Preparing is not sending; external copies cannot be recalled.')}</dd></div><div><dt>{t('设备同步和连接访问','Device sync and connected access')}</dt><dd>{t('需要独立的产品与授权边界。通用云同步及真实外部 AI 读取连接器不是当前上线承诺。','Require independent product and permission boundaries. General cloud sync and a real external AI reader connector are not current release claims.')}</dd></div></dl><p>{t('隐藏、从主题移除、从档案移除、永久删除与“不能用于 AI”也不是同一个动作。过滤只是阅读可见性，不是删除，更不是授权。删除在 PAIA 可控制的范围内生效，不承诺删除第三方平台或你已导出的副本。','Hiding, removing from a topic, removing from the archive, permanent deletion and excluding from AI use are different actions. Filtering changes reading visibility, not deletion or permission. PAIA deletion applies within its control, not to third-party platforms or copies already exported.')}</p></section><section id="exit"><h2>{t('值得托付，也应该方便离开。','Worth keeping. Possible to leave.')}</h2><p>{t('开放导出用于带走可理解的材料，备份用于恢复整个库。当前代码已有相关路径，但真实大库、私人官方导出及消费级分发的部分验证仍未完成。Beta 不是唯一副本；更新或恢复之前，先确认独立备份。','Open export lets you take understandable material with you; backup is for library recovery. Those paths exist in the current code, but parts of real large-library, private official-export and consumer-distribution verification are still incomplete. Beta should not be your only copy. Check independent backups before updating or restoring.')}</p><p>{t('原平台删除聊天，不会自动删除 PAIA 已保存的内容。你在 PAIA 的删除，也不能自动删除原平台上的聊天。','Deleting a chat on the original platform does not automatically delete content already kept in PAIA. Deleting in PAIA does not automatically delete the original chat.')}</p><p>{a('status.html',t('当前能力与验证边界','Current capability and verification boundaries'),'text-link')}</p></section><section><h2>{t('这个网站本身呢？','What about this website?')}</h2><p>{t('没有分析脚本、广告跟踪器、远程字体或档案连接。示例输入只在本页内存中使用，刷新即清除。只有你主动提交 Beta 申请时，表单信息才会经 FormSubmit 发送到项目邮箱。网站托管与表单服务仍有各自的数据处理边界。','No analytics scripts, ad trackers, remote fonts or archive connection. Sample inputs live only in page memory and clear on reload. Only submitting a beta application sends its fields through FormSubmit to the project email. Website hosting and the form provider have their own data-processing boundaries.')}</p><p>{a('privacy-policy.html',t('阅读隐私政策','Read the privacy policy'),'text-link')}</p></section></div></section>{invitation()}'''
    shell('principles.html',t('PAIA — 数据与信任','PAIA — Data and trust'),t('了解 PAIA 的本地存储、来源保真、用户编辑、AI 授权、复制导出与备份边界。','Understand PAIA’s local storage, source fidelity, editing, AI permission, export and backup boundaries.'),trust)

    status=f'''<section class="page-intro wrap"><p class="eyebrow">{t('当前状态 · 核对于 2026-09-26','CURRENT STATUS · REVIEWED 26 SEP 2026')}</p><h1>{t('把已经做到的，<br>和接下来要做的分开。','What exists.<br>What is still ahead.')}</h1><p class="lead">{t('PAIA 正在 Private Beta 中迭代。已有实现不等于所有场景都通过真实环境认证，也不等于已经公开发布。','PAIA is evolving in private beta. An implemented capability is not the same as full real-world certification or a public release.')}</p>{statusmini()}</section><section class="status-page wrap"><article><span class="label">{t('01 / 当前代码已有','01 / IMPLEMENTED IN THE CURRENT BUILD')}</span><h2>{t('保存、找回，以及明确的再次使用。','Capture, revisit, and deliberate reuse.')}</h2><ul><li>{t('经同意采集支持的 ChatGPT 页面中符合条件、已显示的用户文字；可暂停。','Consent-based capture of eligible, displayed user text on supported ChatGPT pages; capture can be paused.')}</li><li>{t('按项目与会话导航、连续阅读、工作文字编辑及词面搜索。编辑和检索体验仍在继续收敛。','Project and conversation navigation, continuous reading, working-text editing and lexical search. Editing and retrieval UX are still being refined.')}</li><li>{t('跨会话主题阅读，以及基于来源材料的可选 AI 整理。AI 输出需要核对。','Cross-conversation topic reading and optional AI organization grounded in source material. AI output needs review.')}</li><li>{t('从输入或主题明确选材料，准备并预览上下文，再复制或导出。材料变化后旧预览失效。','Explicit material selection from inputs or topics, context preparation and preview, then copy or export. Changed material invalidates an old preview.')}</li><li>{t('开放导出、分段备份与分阶段恢复的实现路径。请参照下方验证限制。','Implemented paths for open export, segmented backup and staged restore. See verification limits below.')}</li></ul></article><article><span class="label">{t('02 / 仍在验证','02 / VERIFICATION IN PROGRESS')}</span><h2>{t('工程测试，不代替真实使用。','Engineering tests are not real-world proof.')}</h2><p>{t('当前仍有真实 ChatGPT 环境、实体设备、签名分发与同身份更新，以及私人官方历史导出等外部证据缺口。大规模合成数据测试已经用于工程验证，但不能冒充你的真实资料已安全恢复。','Remaining external evidence includes live ChatGPT journeys, physical devices, signed distribution and same-identity updates, and private official history exports. Large synthetic datasets have been used in engineering tests; that is not proof that your real archive has been safely restored.')}</p><p>{t('因此，目前不承诺一键完整导入全部历史、所有来源兼容、无限容量、无损的十年保存保证或公开商店即装即用。','We do not currently promise one-click import of all history, universal source compatibility, unlimited capacity, a ten-year lossless-storage guarantee, or immediate public-store installation.')}</p></article><article><span class="label">{t('03 / 后续方向，尚非当前上线能力','03 / FUTURE DIRECTION, NOT CURRENT AVAILABILITY')}</span><h2>{t('让更多表达继续有用，<br>但不提前借未来作承诺。','More ways to keep thinking.<br>No borrowing from the future.')}</h2><p>{t('真正的外部 AI 读取连接器、更强语义检索、更多个人表达来源、手机上的快速记录与语音，以及独立授权的跨设备能力，属于后续产品方向。它们不应从官网示意图被误读为已经完整可用。','A real external AI reader connector, stronger semantic retrieval, more sources of personal expression, quick writing and voice on mobile, and separately authorized cross-device capabilities are future directions. Website illustrations should not imply that these are already fully available.')}</p></article><div class="status-footnote"><p>{t('本页依据仓库已合入的实现与 Consumer Product v1 状态核对，不把 open PR 当作已发布能力。技术状态会继续变化，获邀时以提供的版本与说明为准。','This page is checked against integrated repository code and Consumer Product v1 status, not open PRs treated as releases. Technical status will continue to evolve; invitations describe the actual build provided.')}</p><a href="https://github.com/haohongfei2001-png/paia" rel="noreferrer">{t('查看公开仓库','View the public repository')} ↗</a></div></section>{invitation()}'''
    shell('status.html',t('PAIA — 当前能力与后续方向','PAIA — Current capabilities and future direction'),t('PAIA Private Beta 的已实现能力、未完成验证和未来方向。明确区分工程实现与生产发布。','Implemented capabilities, incomplete verification and future directions for the PAIA private beta.'),status)

    about=f'''<section class="page-intro wrap"><p class="eyebrow">WHY PAIA</p><h1>{t('你在对话里投入的，<br>不应该只属于那次对话。','What you put into a chat<br>should outlast that chat.')}</h1></section><article class="prose about-prose wrap"><p class="lead">{t('我们越来越多地借助 AI 想事情。写下背景，解释选择，推翻假设，反复描述自己在意什么。久而久之，这些不只是输入，它们也是我们留给自己的材料。','More of our thinking now happens with AI. We explain the background, weigh a choice, question an assumption, and describe what matters. Over time, these are more than inputs. They are material we have made for ourselves.')}</p><p>{t('PAIA 从一个小问题开始：这些已经自然产生的表达，能不能更容易被自己找回、理解、修正，然后继续使用？不是要求人再经营一个知识库，也不是让 AI 默认知道一切。','PAIA began with a small question: could the expressions we already produce become easier to recover, understand, revise and reuse? Not by asking people to maintain another knowledge base. Not by giving AI access to everything.')}</p><h2>{t('先为人可读，再为 AI 可用。','Readable for you. Reusable with AI.')}</h2><p>{t('Input Archive 留住具体内容和来源。Thought Library 帮助跨会话看一个长期主题。AI Context 让你为这次任务选择要用的部分。它们共同服务一个过程：留下、回看、理解、复用。','Input Archive keeps concrete material and its source. Thought Library helps you see a lasting topic across chats. AI Context lets you choose what belongs in the next task. Together they serve one loop: capture, revisit, understand, reuse.')}</p><p>{t('这是一个持续设计与开发中的独立项目。真实价值要由长期使用来证明：有没有更容易找回，愿不愿意回来，能不能少重复一次，继续想深一点。功能数量和测试通过，不能代替这些答案。','This is an independently developed product in active iteration. Its value must be established through lasting use: easier retrieval, a reason to return, less repetition, and room to think further. Feature counts and passing tests cannot answer those questions.')}</p><p>{a('demo.html',t('从一个示例开始','Start with one example'),'text-link')}</p></article>{invitation()}'''
    shell('about.html',t('为什么做 PAIA','Why PAIA exists'),t('PAIA 为什么存在：让在 AI 对话中自然产生的表达，成为自己可找回、理解、修改和复用的私人材料。','Why PAIA exists: to make the expressions you naturally create in AI conversations recoverable, understandable, editable and reusable.'),about)

    privacy_sections=[
      (t('1. 核心原则','1. Core principles'),t('PAIA 当前以本地优先方式运行。核心档案数据默认保存在用户设备上，产品设计优先让保存、检索、备份和多数组织逻辑在本地完成。','PAIA currently operates local-first. Core archive data is stored on the user’s device by default. The product prioritizes local capture, retrieval, backup and most organization logic.')),
      (t('2. AI 相关数据使用','2. AI-related data use'),t('PAIA 不默认把完整档案交给外部 AI。需要调用外部 AI 的功能，应由用户明确触发，并尽量只处理完成当前任务所必要的内容。AI Context 的授权、排除和预览应当先由用户确认。','PAIA does not give external AI the complete archive by default. Features that call external AI should be explicitly triggered by the user and process only what is needed for the task. AI Context permissions, exclusions and previews should be confirmed by the user first.')),
      (t('3. 本网站','3. This website'),t('当前公开展示网站不连接用户的 PAIA 档案，也不设置分析脚本或行为跟踪器。网站仅用于说明产品理念、交互与当前开发状态。','This public website does not connect to a user’s PAIA archive or install analytics scripts or behavioral trackers. It explains the product, interactions and current development status.')),
      (t('4. Private Beta 申请','4. Private beta applications'),t('Private Beta 申请表通过第三方表单转发服务 FormSubmit 将你主动填写的信息发送到项目联系邮箱 haohongfei2001@gmail.com。申请信息仅用于当前 Beta 的招募、筛选与联系，并会在不再需要用于 Beta 招募后删除。你可以随时通过项目联系邮箱要求提前删除已提交的申请信息。请不要提交敏感信息。','The private beta form uses the third-party forwarding service FormSubmit to send the information you enter to haohongfei2001@gmail.com. Application information is used only for current beta recruitment, selection and contact, and is deleted when no longer needed for recruitment. You can request earlier deletion through the project email at any time. Do not submit sensitive information.')),
      (t('5. Private Beta','5. Private beta'),t('PAIA 仍处于 Private Beta。具体数据结构、同步方式和可选 AI 功能可能继续调整。若未来引入云同步、账户系统或新的外部服务，会在正式启用前更新本政策并说明相应数据边界。','PAIA remains in private beta. Data structures, synchronization approaches and optional AI features may change. If cloud sync, accounts or new external services are introduced, this policy will be updated and their data boundaries explained before activation.')),
      (t('6. 用户控制与删除','6. User control and deletion'),t('产品目标是让用户保留对自己档案的最终控制权，包括查看、编辑、导出和删除。具体能力以当前 Beta 版本实际提供的功能为准。','The product aims to keep users in control of their archives, including viewing, editing, exporting and deleting. Specific capabilities depend on what the current beta build actually provides.'))]
    terms_sections=[
      (t('1. Beta 状态','1. Beta status'),t('PAIA 当前处于 Private Beta。功能、数据结构、界面和支持范围可能持续变化，部分能力可能不稳定或暂时不可用。','PAIA is currently in private beta. Features, data structures, interfaces and support scope may change. Some capabilities may be unstable or temporarily unavailable.')),
      (t('2. 用户数据','2. User data'),t('用户对自己输入、编辑和导入的内容保留相应权利。PAIA 的产品目标是让这些内容保持可查看、可管理和可导出，而不是通过锁定用户数据建立使用门槛。','Users retain the relevant rights in content they enter, edit and import. PAIA aims to make this material viewable, manageable and exportable, rather than create barriers by locking in user data.')),
      (t('3. 备份责任','3. Backups'),t('在 Beta 阶段，用户不应把 PAIA 作为自己重要数据的唯一副本。对于需要长期保存的内容，请同时保留独立备份。','During beta, do not use PAIA as the only copy of important data. Keep independent backups of material that needs long-term preservation.')),
      (t('4. 合理使用','4. Acceptable use'),t('请勿利用 PAIA 进行违法活动、未经授权的数据收集、侵犯他人隐私或知识产权，或规避第三方平台的访问和使用限制。','Do not use PAIA for unlawful activity, unauthorized data collection, violations of others’ privacy or intellectual property, or circumvention of third-party access and usage restrictions.')),
      (t('5. 第三方服务','5. Third-party services'),t('PAIA 可能与浏览器、AI 服务或其他第三方平台配合使用。第三方服务的可用性、条款和技术变化不由 PAIA 控制，相关功能可能因此调整。','PAIA may work with browsers, AI services and other third-party platforms. PAIA does not control their availability, terms or technical changes, which may require changes to related features.')),
      (t('6. 可用性与责任边界','6. Availability and limitations'),t('Beta 版本按当前状态提供，不承诺持续、无错误或永久可用。产品会尽力降低数据风险，但用户仍应为重要资料保留独立备份。','The beta is provided in its current state, without a promise of continuous, error-free or permanent availability. The product seeks to reduce data risks, but users should keep independent backups of important material.'))]
    for page,title,sections,date in [('privacy-policy.html',t('隐私政策','Privacy policy'),privacy_sections,'2026-09-11'),('terms.html',t('使用条款','Terms'),terms_sections,'2026-09-10')]:
        content=f'''<section class="page-intro wrap"><p class="eyebrow">PAIA · PRIVATE BETA</p><h1>{title}</h1><p class="small">{t('政策内容最后更新','Policy content last updated')}: {date} · {t('页面呈现更新','Presentation updated')}: 2026-09-26</p></section><article class="prose legal-prose wrap">{''.join(f'<section><h2>{h}</h2><p>{p}</p></section>' for h,p in sections)}<section><h2>{t('7. 联系','7. Contact')}</h2><p>{t('有关本政策、Beta 或申请信息删除的问题，请联系','For policy, beta or application-deletion questions, contact')} <a href="mailto:{EMAIL}">{EMAIL}</a>{t("。", ".")}</p></section>{f'<aside class="notice"><p>{t("网站示例补充说明：示例输入只在当前页面内存中使用，不上传或持久保存；刷新即清除。网站托管和 FormSubmit 仍有各自的数据处理边界。", "Website sample clarification: inputs are used only in current-page memory, not uploaded or persisted, and clear on reload. Website hosting and FormSubmit have their own data-processing boundaries.")}</p>{a("principles.html",t("查看具体的数据与授权边界","Read the practical data boundaries"))}</aside>' if page=='privacy-policy.html' else ''}</article>'''
        shell(page,'PAIA — '+title,t('PAIA Private Beta 的隐私和使用边界。','Privacy and usage boundaries for the PAIA private beta.'),content)
    thanks=f'''<section class="page-intro compact-intro wrap"><p class="eyebrow">PAIA · PRIVATE BETA</p><h1>{t('接下来，留意你的邮箱。','Next, keep an eye on your inbox.')}</h1><p class="lead">{t('申请不等于获得测试资格。若收到邀请，你会获得安装说明、当前限制与反馈方式。','An application is not an invitation. Invited participants receive setup instructions, current limitations and a feedback path.')}</p><p>{t('此页面本身不确认表单是否送达。没有看到 FormSubmit 的成功结果，或提交时遇到错误？请返回重试，或直接写信联系。','This page alone does not confirm delivery. If you did not see a successful FormSubmit response, or encountered a submission error, return to the form or email us directly.')}</p><div class="actions">{button('index.html',t('回到 PAIA','Back to PAIA'))}{a('beta.html',t('返回申请表','Return to the form'),'text-link')}</div><p class="small"><a href="mailto:{EMAIL}">{EMAIL}</a></p></section>'''
    shell('thanks.html',t('PAIA — 申请后的下一步','PAIA — After applying'),t('Private Beta 申请后的下一步与联系渠道。','Next steps and contact after applying to the private beta.'),thanks,True)
    notfound=f'''<section class="page-intro compact-intro wrap"><p class="eyebrow">404</p><h1>{t('这页没有找到。','This page wasn’t found.')}</h1><p class="lead">{t('链接可能已变化。你的扩展档案不在这个网站里，不受影响。','The link may have changed. Your extension archive is not stored on this website and is unaffected.')}</p><div class="actions">{button('index.html',t('回到首页','Back to home'))}{a('demo.html',t('体验示例','Try the sample'),'text-link')}</div></section>'''
    shell('404.html',t('PAIA — 页面未找到','PAIA — Page not found'),t('返回 PAIA 首页。','Return to the PAIA homepage.'),notfound,True)

for lang in ['zh','en']: build(lang)
# Absolute root paths target the existing custom-domain root deployment.
urls=[]
for locale in ['', 'en/']:
    for name in ['', 'beta.html','principles.html','status.html','about.html','privacy-policy.html','terms.html']:
        urls.append(f'<url><loc>{BASE}/{locale}{name}</loc></url>')
write(ROOT/'sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(urls)+'</urlset>\n')
write(ROOT/'robots.txt','User-agent: *\nAllow: /\nSitemap: https://inputarchive.com/sitemap.xml\n')
if CHECK:
    changed=[name for name,body in GENERATED.items() if not (ROOT/name).exists() or (ROOT/name).read_text(encoding='utf-8')!=body]
    if changed: raise SystemExit('Generated website drift: '+', '.join(changed))
else:
    (ROOT/'website/generated-paths.txt').write_text('\n'.join(sorted(GENERATED))+'\n',encoding='utf-8')
print(('Checked' if CHECK else 'Generated'),len(GENERATED),'website files')
